import { formatDate, Given, When, Then } from './formatter';

describe('Date Formatter', () => {
    Given('a date object representing January 1, 2023', () => {
        const date = new Date('2023-01-01');

        When('formatting the date', () => {
            const result = formatDate(date);

            Then('it should return "2023-01-01"', () => {
                expect(result).toBe('2023-01-01');
            });
        });
    });

    Given('a date object representing December 31, 1999', () => {
        const date = new Date('1999-12-31');

        When('formatting the date', () => {
            const result = formatDate(date);

            Then('it should return "1999-12-31"', () => {
                expect(result).toBe('1999-12-31');
            });
        });
    });

    Given('a date object representing February 29, 2020 (leap year)', () => {
        const date = new Date('2020-02-29');

        When('formatting the date', () => {
            const result = formatDate(date);

            Then('it should return "2020-02-29"', () => {
                expect(result).toBe('2020-02-29');
            });
        });
    });

    Given('a date object with time components', () => {
        const date = new Date('2023-05-15T14:30:45.123Z');

        When('formatting the date', () => {
            const result = formatDate(date);

            Then('it should return only the date part "2023-05-15"', () => {
                expect(result).toBe('2023-05-15');
            });
        });
    });

    Given('a date object representing the current date', () => {
        const date = new Date();

        When('formatting the date', () => {
            const result = formatDate(date);

            Then('it should return the current date in YYYY-MM-DD format', () => {
                const expected = date.toISOString().split('T')[0];
                expect(result).toBe(expected);
            });
        });
    });

    Given('a date object representing January 1, 1970 (Unix epoch)', () => {
        const date = new Date('1970-01-01');

        When('formatting the date', () => {
            const result = formatDate(date);

            Then('it should return "1970-01-01"', () => {
                expect(result).toBe('1970-01-01');
            });
        });
    });

    Given('a date object representing a single digit month and day', () => {
        const date = new Date('2023-03-05');

        When('formatting the date', () => {
            const result = formatDate(date);

            Then('it should return "2023-03-05" with leading zeros', () => {
                expect(result).toBe('2023-03-05');
            });
        });
    });

    Given('null as input', () => {
        const date = null as any;

        When('formatting the date', () => {
            Then('it should throw an error', () => {
                expect(() => formatDate(date)).toThrow('Invalid date');
            });
        });
    });

    Given('undefined as input', () => {
        const date = undefined as any;

        When('formatting the date', () => {
            Then('it should throw an error', () => {
                expect(() => formatDate(date)).toThrow('Invalid date');
            });
        });
    });

    Given('an invalid date object', () => {
        const date = new Date('invalid');

        When('formatting the date', () => {
            Then('it should throw an error', () => {
                expect(() => formatDate(date)).toThrow('Invalid date');
            });
        });
    });

    Given('a non-date object as input', () => {
        const date = '2023-01-01' as any;

        When('formatting the date', () => {
            Then('it should throw an error', () => {
                expect(() => formatDate(date)).toThrow('Invalid date');
            });
        });
    });
});

